"use strict";
function activateGameCode(code){code=String(code).trim();if(code==='1248'){const v=victoryState();if(!v.won){v.byCode=true;awardWorldVictory();}else{v.dismissed=false;renderVictory(true)}$('codeStatus').textContent='Kod 1248 aktywny — zwycięstwo!';say('Kod 1248: '+(isDesertCampaign()?'Ostateczne zwycięstwo!':'Dolina ukończona — pustynia odblokowana!'));return true}if(code!=='1423'){$('codeStatus').textContent='Nieprawidłowy kod.';return false}state.fullMap=true;for(const t of state.towns)t.discovered=true;atlasTerrainSignature='';atlasListSignature='';warPanelSignature='';save();ui();$('codeStatus').textContent='Kod 1423 aktywny — odkryto całą mapę i wszystkie osady.';say('Odkryto całą mapę! Otwórz Mapę świata (M).');return true}
const codesPanel=document.createElement('aside');codesPanel.id='codesPanel';codesPanel.className='war-panel hidden';codesPanel.innerHTML='<div class="war-title"><h2>Kody gry</h2><button id="codesClose" aria-label="Zamknij kody">✕</button></div><p>Wpisz kod, aby aktywować jego działanie.</p><label for="gameCode">Kod</label><input id="gameCode" type="text" inputmode="numeric" maxlength="20" autocomplete="off"><button id="codeActivate">Aktywuj kod</button><p id="codeStatus" role="status"></p>';document.body.append(codesPanel);const codesOpen=document.createElement('button');codesOpen.textContent='⌨ Kody gry';codesOpen.onclick=()=>{$('codesPanel').classList.remove('hidden');$('gameCode').focus()};$('clockControls').append(codesOpen);$('codesClose').onclick=()=>$('codesPanel').classList.add('hidden');$('codeActivate').onclick=()=>activateGameCode($('gameCode').value);$('gameCode').addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Enter')activateGameCode(e.target.value);if(e.key==='Escape')$('codesPanel').classList.add('hidden')});
